import{_ as l,a0 as o,w as d,s as r,I as a,x as n,a1 as t,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"Systemd 服務：比啓動停止服務更進一步 | LCTT x X-CMD","titleTemplate":false,"description":"Systemd 服務：比啓動停止服務更進一步 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Systemd 服務：比啓動停止服務更進一步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Systemd 服務：比啓動停止服務更進一步 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180507 Systemd Services- Beyond Starting and Stopping","title":"Systemd 服務：比啓動停止服務更進一步","tag":"201806","desc":""},"relativePath":"201806/20180507 Systemd Services- Beyond Starting and Stopping.md","filePath":"[post].md"}'),c={name:"201806/20180507 Systemd Services- Beyond Starting and Stopping.md"};function m(g,s,u,h,b,k){const e=o("Link");return d(),r("div",null,[s[21]||(s[21]=a("h1",{id:"systemd-服務-比啓動停止服務更進一步",tabindex:"-1"},[n("Systemd 服務：比啓動停止服務更進一步 "),a("a",{class:"header-anchor",href:"#systemd-服務-比啓動停止服務更進一步","aria-label":"Permalink to “Systemd 服務：比啓動停止服務更進一步”"},"​")],-1)),s[22]||(s[22]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/systemd-minetest-2.jpg?itok=bXO0ggHL",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("在上一篇",-1)),t(e,{href:"https://linux.cn/article-9700-1.html"},{default:i(()=>[...s[0]||(s[0]=[n("文章",-1)])]),_:1}),s[2]||(s[2]=n("中，我們展示瞭如何創建一個 systemd 服務並使普通用户可以啓動和終止遊戲服務器。但到目前為止，使用這個服務並不比直接運行服務器高明多少。讓我們更進一步，讓其可以向玩家發郵件，包括在服務器可用時通知玩家，在服務器關閉前警告玩家：",-1))]),s[23]||(s[23]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># minetest.service</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description= Minetest server</span></span>
<span class="line"><span>Documentation= https://wiki.minetest.net/Main_Page</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type= simple</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ExecStart= /usr/games/minetest --server</span></span>
<span class="line"><span>ExecStartPost= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Ready to rumble?&quot; &quot;Minetest Starting up&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TimeoutStopSec= 180</span></span>
<span class="line"><span>ExecStop= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Off to bed. Nightie night!&quot; &quot;</span></span>
<span class="line"><span>  Minetest Stopping in 2 minutes&quot;</span></span>
<span class="line"><span>ExecStop= /bin/sleep 120</span></span>
<span class="line"><span>ExecStop= /bin/kill -2 $MAINPID</span></span></code></pre></div><p>這裏涉及幾個新的指令。首先是 <code>ExecStartPost</code> 指令，該指令可以在主進程啓動後馬上執行任何你指定的操作。在本例中，你執行了一個自定義腳本 <code>mtsendmail</code> (內容如下)，該腳本以郵件形式通知你的朋友服務器已經啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span># mtsendmail</span></span>
<span class="line"><span>echo $1 | mutt -F /home/&lt;username&gt;/.muttrc -s &quot;$2&quot; my_minetest@mailing_list.com</span></span></code></pre></div>`,3)),a("p",null,[s[4]||(s[4]=n("我們使用 ",-1)),t(e,{href:"http://www.mutt.org/"},{default:i(()=>[...s[3]||(s[3]=[n("Mutt",-1)])]),_:1}),s[5]||(s[5]=n(" 這個命令後郵件客户端發送消息。雖然從實際效果來看，上述腳本僅有 1 行，但 systemd 單元的參數中不能包含管道及重定向操作，故我們需要將其封裝到腳本中。",-1))]),s[24]||(s[24]=p(`<p>順便提一下，還有一個 <code>ExecStartPre</code> 指令，用於在服務主進程執行之前進行指定操作。</p><p>接下來我們看到，關閉服務器涉及了好幾條指令。<code>TimeoutStopSec</code> 指令用於設置 systemd 友好關閉服務的最大等候時間，默認值大約是 90 秒。超過這個最大等候時間，systemd 會強制關閉服務並報錯。考慮到你希望在徹底關閉服務器前給用户預留幾分鐘的時間，你需要將超時時間提高至 3 分鐘，這樣 systemd 就不會誤認為服務關閉時出現問題。</p><p>接下來是關閉服務的具體指令部分。雖然沒有 <code>ExecStopPre</code> 這樣的指令，但你可以通過多次使用 <code>ExecStop</code> 指令實現關閉服務器前執行操作的目標。多個 <code>ExecStop</code> 指令按從上到下的順序依次運行，這樣你就可以在服務器真正關閉前向用户發送消息。</p><p>通過這個特性，你首先應該向你的朋友發郵件，警告其服務器即將關閉，然後等待兩分鐘，最後關閉服務器。可以使用 <code>Ctrl + c</code> 關閉 Minetest 服務器，該操作會被轉換為一箇中斷信號（<code>SIGINT</code>）；當你執行 <code>kill -2 $MAINPID</code> 時就會發送該中斷信號，其中 <code>$MAINPID</code> 是 systemd 變量，用於記錄你服務中主進程的 PID 信息。</p><p>看上去好多了！如果你此時啓動服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl --user start minetest</span></span></code></pre></div><p>服務會啓動 Minetest 服務器並向你的用户發送郵件。關閉服務的情形基本類似，只不過會額外留給用户 2 分鐘時間退出登錄。</p><h3 id="開機自啓動" tabindex="-1">開機自啓動 <a class="header-anchor" href="#開機自啓動" aria-label="Permalink to “開機自啓動”">​</a></h3><p>下一步我們讓你的服務在主機啓動後立即可用，在主機關閉時自動關閉。</p><p>我們需要將你的服務文件移動到系統服務目錄，即 <code>/etc/systemd/system/</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mv /home/&lt;username&gt;/.config/systemd/user/minetest.service /etc/systemd/system/</span></span></code></pre></div><p>如果你希望此時啓動該服務，你需要擁有超級用户權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start minetest</span></span></code></pre></div><p>另外，可以使用如下命令檢查服務狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl status minetest</span></span></code></pre></div><p>你會發現服務很糟糕地處於失敗狀態，這是因為 systemd 不能通過上下文信息、特徵、配置文件得知具體使用哪個用户運行該服務。在單元文件中增加 <code>User</code> 指令可以解決這個問題。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># minetest.service</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description= Minetest server</span></span>
<span class="line"><span>Documentation= https://wiki.minetest.net/Main_Page</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type= simple</span></span>
<span class="line"><span>User= &lt;username&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ExecStart= /usr/games/minetest --server</span></span>
<span class="line"><span>ExecStartPost= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Ready to rumble?&quot;</span></span>
<span class="line"><span>  &quot;Minetest Starting up&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TimeoutStopSec= 180</span></span>
<span class="line"><span>ExecStop= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Off to bed. Nightie night!&quot;</span></span>
<span class="line"><span>  &quot;Minetest Stopping in 2 minutes&quot;</span></span>
<span class="line"><span>ExecStop= /bin/sleep 120</span></span>
<span class="line"><span>ExecStop= /bin/kill -2 $MAINPID</span></span></code></pre></div><p>systemd 從 <code>User</code> 指令中得知應使用哪個用户的環境變量來正確運行該服務。你可以使用 root 用户，但這可能產生安全風險；使用你的個人用户會好一些，但不少管理員的做法是為服務單獨創建一個用户，這樣可以有效地將服務與其它用户和系統組件相互隔離。</p><p>下一步我們讓你的服務在系統啓動時自動啓動，系統關閉時自動關閉。要達到這個目的，你需要 <em>啓用</em> 你的服務；但在這之前，你還需要告知 systemd 從哪裏 <em>安裝</em> 它。</p><p>對於 systemd 而言，<em>安裝</em> 意味着告知 systemd 在系統啓動的具體哪個步驟激活你的服務。以通用 Unix 打印系統（<code>cups.service</code>）為例，它的啓動在網絡框架啓動之後、其它打印服務啓動之前。又如，<code>minetest.server</code> 需要使用用户郵件（及其它組件），需要等待網絡和普通用户對應的服務就緒後才可啓動。</p><p>你只需要在單元文件中添加一個新段和新指令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy= multi-user.target</span></span></code></pre></div><p>你可以將其理解為“等待多用户系統的全部內容就緒”。systemd 中的“目標”類似於舊系統中的運行級別，可以用於將主機轉移到一個或另一個狀態，也可以像本例中這樣讓你的服務等待指定狀態出現後運行。</p><p>你的最終 <code>minetest.service</code> 文件如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># minetest.service</span></span>
<span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description= Minetest server</span></span>
<span class="line"><span>Documentation= https://wiki.minetest.net/Main_Page</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type= simple</span></span>
<span class="line"><span>User= &lt;username&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ExecStart= /usr/games/minetest --server</span></span>
<span class="line"><span>ExecStartPost= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Ready to rumble?&quot;</span></span>
<span class="line"><span>  &quot;Minetest Starting up&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TimeoutStopSec= 180</span></span>
<span class="line"><span>ExecStop= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Off to bed. Nightie night!&quot;</span></span>
<span class="line"><span>  &quot;Minetest Stopping in 2 minutes&quot;</span></span>
<span class="line"><span>ExecStop= /bin/sleep 120</span></span>
<span class="line"><span>ExecStop= /bin/kill -2 $MAINPID</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy= multi-user.target</span></span></code></pre></div><p>在嘗試新的服務之前，你還需要對郵件腳本做一些調整：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span># mtsendmail</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sleep 20</span></span>
<span class="line"><span>echo $1 | mutt -F /home/&lt;username&gt;/.muttrc -s &quot;$2&quot; my_minetest@mailing_list.com</span></span>
<span class="line"><span>sleep 10</span></span></code></pre></div><p>這是因為系統需要一定的時間啓動郵件系統（這裏等待 20 秒），也需要一定時間完成郵件發送（這裏等待 10 秒）。注意腳本中的等待時間數值適用於我的系統，你可能需要針對你的系統調整數值。</p><p>大功告成啦。執行如下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable minetest</span></span></code></pre></div><p>你的 Minetest 服務將在系統啓動時自動啓動，在系統關閉時友好關閉並通知你的用户。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>事實上 Debian、 Ubuntu 和一些族類的發行版提供了 <code>minetest-server</code> 這個特別的軟件包，可以提供一部分上述功能，（但不包括郵件通知功能）。即使如此，你還是可以建立你獨有的自定義服務；事實上，你目前建立的服務比 Debian 默認提供的服務更加通用，可以提供更多功能。</p><p>更進一步的説，我們這裏描述的流程可以讓你將大多數簡單服務器轉換為服務，類型可以是遊戲、網站應用或其它應用。同時，這也是你名副其實地踏入 systemd 大師殿堂的第一步。</p><hr>`,35)),a("p",null,[s[7]||(s[7]=n("via: ",-1)),t(e,{href:"https://www.linux.com/blog/learn/2018/5/systemd-services-beyond-starting-and-stopping"},{default:i(()=>[...s[6]||(s[6]=[n("https://www.linux.com/blog/learn/2018/5/systemd-services-beyond-starting-and-stopping",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=n("作者：",-1)),t(e,{href:"https://www.linux.com/users/bro66"},{default:i(()=>[...s[8]||(s[8]=[n("Paul Brown",-1)])]),_:1}),s[13]||(s[13]=n(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[9]||(s[9]=[n("lujun9972",-1)])]),_:1}),s[14]||(s[14]=n(" 譯者：",-1)),t(e,{href:"https://github.com/pinewall"},{default:i(()=>[...s[10]||(s[10]=[n("pinewall",-1)])]),_:1}),s[15]||(s[15]=n(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[11]||(s[11]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[16]||(s[16]=[n("LCTT",-1)])]),_:1}),s[19]||(s[19]=n(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[17]||(s[17]=[n("Linux中國",-1)])]),_:1}),s[20]||(s[20]=n(" 榮譽推出",-1))])])}const x=l(c,[["render",m]]);export{S as __pageData,x as default};
